{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Delpazolid, the closest analogue sharing the same oxazolidinone core, C5 hydroxymethyl, and ortho-fluorophenyl substitution, showed near-complete absolute oral bioavailability (~100%) in humans after oral dosing versus IV.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Linezolid, a same-class oxazolidinone with the identical N-aryl oxazolidinone core, has essentially 100% absolute oral bioavailability in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Contezolid, another oxazolidinone with the same core, showed an absolute bioavailability of 0.64 in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808, a same-core oxazolidinone with a thiomorpholine substituent and acetamidomethyl side chain, had low absolute bioavailability (10.1%), providing contradictory evidence; however, the query lacks the thiomorpholine and acetamide features, reducing its relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an oxazolidinone with a C5 hydroxymethyl group and a methyltetrazolyl-pyridine aryl substituent, closely related to delpazolid and linezolid, both of which show near-complete human oral bioavailability. The closest analogue, delpazolid, shares the same oxazolidinone/hydroxymethyl/fluorophenyl core and shows ~100% F. Linezolid and contezolid independently support high F. The only same-scaffold low-F analogue, YH4808, differs by a thiomorpholine moiety and C5 acetamide, which are not present in the query; its low F is outweighed by the higher-transfer and structurally more relevant high-F evidence. Therefore, the query is predicted to have F >= 20%.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability measurement for the query molecule itself.",
    "The closest analogue delpazolid is highly similar but not identical; the exact effect of the methyltetrazolyl-pyridine substituent on human F is not directly measured in this dataset.",
    "The mechanism underlying YH4808's low bioavailability is not fully explained, limiting certainty about whether similar liabilities could apply."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

